// Builds src/preload/webauthn-preload.js from src/browser/webauthn-gate.js. The preload is registered on every tab
// session as a 'frame' preload and is sandboxed, so it can only require('electron'): the two page-world functions are
// copied into it as source. The output is committed; test/webauthn-gate-units.js checks it still matches this
// script's output. Run after changing webauthn-gate.js:  node scripts/bundle-webauthn-preload.js
const fs = require('fs');
const path = require('path');

const ROOT = path.join(__dirname, '..');
const OUT = path.join(ROOT, 'src', 'preload', 'webauthn-preload.js');

function bundle() {
  const { hideWebAuthn, installPasskeys } = require(path.join(ROOT, 'src', 'browser', 'webauthn-gate.js'));
  return [
    '// Generated by scripts/bundle-webauthn-preload.js from browser/webauthn-gate.js. Do not edit; edit that file and rerun it.',
    '//',
    '// Passkeys / Windows Hello / security keys (WebAuthn) in every frame of every tab. The main process says which mode',
    "// this frame gets (features/passkeys.js, 'webauthn:mode'): 'native' bridges navigator.credentials to Windows' own",
    "// WebAuthn through the main process, which checks every request; 'hide' takes the API away so sites offer a password",
    '// or a code instead of a prompt Electron cannot show. Anything unexpected here means hide.',
    "const { contextBridge, ipcRenderer } = require('electron');",
    '',
    hideWebAuthn.toString(),
    '',
    installPasskeys.toString(),
    '',
    'let mode;',
    "try { mode = ipcRenderer.sendSync('webauthn:mode'); } catch { mode = null; }",
    'try {',
    "  if (mode && mode.mode === 'native') {",
    '    // Read in this (isolated) world when the page asks, where the page cannot fake them; the main process decides.',
    '    const allows = (feature) => { try { const fp = document.featurePolicy; return fp ? fp.allowsFeature(feature) : null; } catch { return null; } };',
    '    const facts = () => ({',
    '      activation: Boolean(navigator.userActivation && navigator.userActivation.isActive),',
    "      policyGet: allows('publickey-credentials-get'),",
    "      policyCreate: allows('publickey-credentials-create'),",
    '    });',
    '    const bridge = {',
    "      request: (kind, id, options) => ipcRenderer.invoke('webauthn:request', { kind: String(kind), id: String(id), options, frame: facts() }),",
    "      cancel: (id) => ipcRenderer.send('webauthn:cancel', String(id)),",
    '    };',
    '    contextBridge.executeInMainWorld({ func: installPasskeys, args: [bridge, mode.caps || {}] });',
    '  } else {',
    '    contextBridge.executeInMainWorld({ func: hideWebAuthn });',
    '  }',
    '} catch (err) {',
    "  console.error('webauthn: could not set up the API:', err.message);",
    '  try { contextBridge.executeInMainWorld({ func: hideWebAuthn }); } catch { /* nothing more to do */ }',
    '}',
    '',
  ].join('\n').replace(/\r\n/g, '\n'); // (a checkout with CRLF endings gives the same file)
}

if (require.main === module) {
  fs.writeFileSync(OUT, bundle());
  console.log(`wrote ${path.relative(ROOT, OUT)}`);
}

module.exports = { bundle };
